reto.codigo:
const exps = [
  { id: 1, estado: "abierto" },
  { id: 2, estado: "cerrado" },
];
function estado(id) {
  const e = exps.find((x) =>
    x.id === id
  );
  if (e === undefined) {
    return "No existe";
  }
  return e.estado;
}
console.log(estado(2));
console.log(estado(5));

